import{_ as t,o as n,c as r,ag as s}from"./chunks/framework.D5hoimZQ.js";const c=JSON.parse('{"title":"🔬 科学日报 | 2026年8月16日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-08-16.md","filePath":"science-log/src/science-daily/2026-08-16.md"}'),e={name:"science-log/src/science-daily/2026-08-16.md"};function g(a,o,i,u,p,q){return n(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="🔬-科学日报-2026年8月16日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年8月16日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年8月16日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年8月16日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：重建版简讯（2026-08-16，共 10 条：科学前沿 5 + AI 前沿 5） 分析日期：2026-08-16 版本：扩展版（10 条深度 + 交叉关联） ⚠️ 本日简讯为<strong>事后重建版</strong>（2026-11-06 按 arXiv/CrossRef 日期回溯生成，非当日发布原文，不代表历史原貌）</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-染色体是-离子水凝胶-有丝分裂凝缩是一次体积相变" tabindex="-1">1. 染色体是&quot;离子水凝胶&quot;：有丝分裂凝缩是一次体积相变 <a class="header-anchor" href="#_1-染色体是-离子水凝胶-有丝分裂凝缩是一次体积相变" aria-label="Permalink to &quot;1. 染色体是&quot;离子水凝胶&quot;：有丝分裂凝缩是一次体积相变&quot;">​</a></h3><p><strong>原文</strong>：Roger D. Kornberg 团队（斯坦福）提出：真核染色体本质上是离子水凝胶，凝缩与解凝缩是同一个物质的两态系统，二者之间的转换是一次体积相变（volume phase transition），与液—气相变同类。</p><p><strong>深度扩展</strong>：</p><p>这项工作由 Andrew J. Beel、Pierre-Jean Matteï 与 Roger D. Kornberg 完成，发表于 <em>Science</em>（2026-08-13），DOI 10.1126/science.adz1083。Kornberg 是核小体结构（1997）与转录起始复合体（2001 前后系列）的奠基者，2006 年诺贝尔化学奖得主——他出手谈&quot;染色体整体态&quot;，本身就说明问题层级被抬高了。</p><p><strong>问题背景</strong>：教科书叙事是&quot;condensin 通过环挤压把染色质缩短&quot;，从而形成中期染色体。但环挤压解释的是<strong>长度</strong>，而中期染色体最惊人的变化是<strong>密度</strong>：同样质量的染色质被压进体积小得多的空间。长度缩短与密度上升是两个独立量，前者不蕴含后者。这是该领域长期被默认绕过的缺口。</p><p><strong>方法</strong>：作者把染色体当作高分子物理里的<strong>离子水凝胶</strong>处理——交联的带电聚合物网络浸在离子溶液中，其平衡体积由网络的弹性回缩力、离子渗透压与聚合物—溶剂相互作用三者竞争决定。当外界条件（离子强度、pH、修饰状态）越过临界点时，网络会不连续地塌缩，即体积相变。作者指出染色体材料恰好处在可以发生这种相变的状态，凝缩态与解凝缩态是同一系统的两个分支，而不是两种不同组装。</p><p><strong>机制指向</strong>：相变的开关被归给<strong>组蛋白尾部与 DNA 之间的离子接触</strong>——乙酰化中和赖氨酸正电荷即断开接触，去乙酰化恢复接触。接触密度改变网络的交联度与相互作用参数，从而推动系统越过相变点。这解释了为什么异染色质（低乙酰化）自发凝缩、常染色质（高乙酰化）自发松散，而不需要&quot;谁去拉&quot;。</p><p><strong>为什么重要</strong>：它把乙酰化调控从&quot;招募某个阅读器的标签&quot;降格为（或者说升格为）<strong>热力学控制变量</strong>。若成立，则凝缩是可预测的相行为，可用离子强度、渗透压、温度去扰动，也可推出可证伪的预测：染色体体积应对离子强度呈现<strong>不连续的跳变</strong>并伴随滞后（hysteresis），而非连续收缩。</p><p><strong>跨主题关联</strong>：这一&quot;交联密度越过临界点即整体塌缩&quot;的图像，与 <code>topics/physics/index.md</code> 里聚合物/软物质相变的讨论同构；也与 <code>topics/ai-brain/index.md</code> 中&quot;约束维持结构、约束移除则退化&quot;的思路呼应——乙酰化移除的是物理交联，正如降低摩擦力移除的是认知约束。</p><hr><h3 id="_2-用机器学习突破织构压电陶瓷的性能天花板" tabindex="-1">2. 用机器学习突破织构压电陶瓷的性能天花板 <a class="header-anchor" href="#_2-用机器学习突破织构压电陶瓷的性能天花板" aria-label="Permalink to &quot;2. 用机器学习突破织构压电陶瓷的性能天花板&quot;">​</a></h3><p><strong>原文</strong>：Jinjing Zhang 等（22 人团队）抓住织构陶瓷相对单晶的独有优势——成分自由度，用机器学习在成分空间搜索，得到 Sm 掺杂的 Pb(In₁/₂Nb₁/₂)O₃–Pb(Sc₁/₂Nb₁/₂)O₃–PbTiO₃ 织构陶瓷：压电系数 d₃₃ 达 1720 pC/N，居里温度 250 °C。</p><p><strong>深度扩展</strong>：</p><p>发表于 <em>Science</em>（2026-08-13），DOI 10.1126/science.aei0475。第一作者 Jinjing Zhang，通讯团队含 Jianglei Chang 等，共 22 位作者——这个规模说明它是一项&quot;材料工程 + 表征 + 理论&quot;全链条协作，而非单点突破。</p><p><strong>问题背景</strong>：压电材料有个经典两难。单晶（如 PMN-PT）d₃₃ 可达 2000 pC/N 以上，但长晶体慢、贵、脆、成分均匀性难控，且加工尺寸受限；陶瓷便宜、结实、易做大面积，但晶粒随机取向把各向异性平均掉，性能长期停在 500–700 pC/N 量级。织构化（texturing）是折中路线：让陶瓷晶粒沿同一方向取向排列，理论上可拿到接近单晶的性能。然而几十年努力下来，织构陶瓷始终没接近单晶——说明瓶颈不在取向度，而在<strong>成分</strong>。</p><p><strong>方法</strong>：作者的关键判断是——单晶受限于相图上的特定化学计量点，而陶瓷可以<strong>任意改成分</strong>，这是织构陶瓷被忽视的自由度。他们用机器学习在 Sm 掺杂的 PIN–PSN–PT 三元体系里搜索成分，避开逐点试错的组合爆炸。得到的最优组分 d₃₃ = 1720 pC/N，居里温度 T_C = 250 °C——同时兼顾了高压电性与高温工作上限（很多高压电性单晶的 T_C 只有 80–100 °C，一到高温就退极化，实用性大减）。</p><p><strong>表征与归因</strong>：原位 X 射线衍射追踪电场下的晶格应变与相变，Rayleigh 分析把总响应拆成<strong>本征贡献</strong>（晶格软化）与<strong>非本征贡献</strong>（畴壁运动）。结论是两者解耦且同时被优化：Sm 掺杂既软化了晶格、又提高了畴壁可动性，而织构保证了这种各向异性响应在宏观上不被平均。</p><p><strong>为什么重要</strong>：这是一条可复制的范式——当某个材料体系&quot;物理上够好了但工艺上做不出来&quot;时，不要硬攻工艺，去找该工艺独有的自由度（这里是成分）并用数据方法搜索。落点是超声换能器、水下声呐、精密位移台与医用成像探头。</p><p><strong>跨主题关联</strong>：与 <code>topics/materials/index.md</code> 中&quot;用机器学习做材料成分/结构搜索&quot;的路线直接续接；性能—温度上限的权衡（d₃₃ vs T_C）是典型的 <code>topics/energysim/index.md</code> 式多目标取舍问题。</p><hr><h3 id="_3-用-化学发光-做超分辨成像-ried-绕过光子预算瓶颈" tabindex="-1">3. 用&quot;化学发光&quot;做超分辨成像：RIED 绕过光子预算瓶颈 <a class="header-anchor" href="#_3-用-化学发光-做超分辨成像-ried-绕过光子预算瓶颈" aria-label="Permalink to &quot;3. 用&quot;化学发光&quot;做超分辨成像：RIED 绕过光子预算瓶颈&quot;">​</a></h3><p><strong>原文</strong>：Wenxin Zhu 等提出 RIED——以熵加权相关 + 反卷积为核心的化学基超分辨成像框架，把&quot;反应发光&quot;从&quot;只能做超灵敏检测&quot;推进到&quot;可做超分辨&quot;。</p><p><strong>深度扩展</strong>：</p><p>发表于 <em>Nature</em>（2026-08-12），DOI 10.1038/s41586-026-10889-7。第一作者 Wenxin Zhu，共 12 位作者。</p><p><strong>问题背景</strong>：超分辨荧光显微的整个技术栈都建立在&quot;外部光激发 → 荧光团发光&quot;这一框架上（STED、STORM/PALM、SIM 皆然）。外部光激发带来三个代价：光毒性、光漂白、背景散射。对活细胞长时程成像，这三者就是硬墙。另一条路是<strong>反应激发发光</strong>——电化学发光（ECL）、化学发光（CL）、生物发光（BL），不靠光子入射而靠化学反应产生激发态，因此天然低背景、高灵敏、生物相容好。但它们长期只能做&quot;超灵敏检测&quot;，做不了&quot;超分辨&quot;，原因很直白：<strong>光子预算太低</strong>。超分辨本质上是靠定位精度或非线性响应换取空间信息，都需要大量光子做统计；单次化学发光事件的光子数远少于激光激发的荧光团。</p><p><strong>方法</strong>：RIED 把问题从&quot;增加光子&quot;改成&quot;更高效地使用已有光子&quot;。它引入<strong>时空记录策略</strong>——不把每一帧当作独立快照，而是把发光事件在时间与空间上的联合分布当作信息载体；再用<strong>熵加权相关</strong>（entropy-weighted correlation）从低信噪数据里提取可用的相关结构（熵加权的作用是抑制高熵噪声区、放大低熵即结构明确的区域），最后用<strong>反卷积</strong>补回光学系统调制传递函数（MTF）造成的频域衰减。这是一个<strong>实验—计算协同</strong>的概念：硬件端改变记录方式，计算端负责重建。</p><p><strong>为什么重要</strong>：如果这条路走通，超分辨就不再必然绑在&quot;强光激发&quot;上。活细胞可以连续观察数小时而不被光毒死、不被漂白——这正是现有超分辨方法最难越过的限制。同时，化学发光可由化学反应速率调控，理论上提供了独立于光强的第二个调制维度。</p><p><strong>跨主题关联</strong>：反卷积 + 频域补偿的数学与 <code>topics/physics/index.md</code> 中的成像/傅里叶光学讨论同源；&quot;用计算换硬件&quot;的思路与 <code>topics/ai-brain/index.md</code> 里&quot;外脑靠关联复利而非更多存储&quot;的结构一致。</p><hr><h3 id="_4-口服-葡萄糖感应益生菌-让肠道自己当血糖传感器" tabindex="-1">4. 口服&quot;葡萄糖感应益生菌&quot;：让肠道自己当血糖传感器 <a class="header-anchor" href="#_4-口服-葡萄糖感应益生菌-让肠道自己当血糖传感器" aria-label="Permalink to &quot;4. 口服&quot;葡萄糖感应益生菌&quot;：让肠道自己当血糖传感器&quot;">​</a></h3><p><strong>原文</strong>：Ningzi Guan 等（13 人）转而做可口服的益生菌活药：以葡萄糖响应转录调控因子 HexR 加人工合成启动子构建葡萄糖传感器，工程菌口服后暂时驻留肠道，当血糖超过正常阈值时启动治疗性转基因表达。</p><p><strong>深度扩展</strong>：</p><p>发表于 <em>Nature</em>（2026-08-12），DOI 10.1038/s41586-026-10909-6。第一作者 Ningzi Guan，共 13 位作者。</p><p><strong>问题背景</strong>：用工程化&quot;设计师细胞&quot;做闭环给药，是合成生物学二十年的目标。已落地的方案分两类：一类靠<strong>外部信号</strong>控制（加一个小分子诱导剂），本质上还是人工开关，不是自主闭环；另一类把合成基因网络装进<strong>哺乳动物细胞</strong>再移植回体内，能自主感应血糖，但带来移植排斥、植入物存活、以及&quot;一旦出错无法撤除&quot;的安全问题。</p><p><strong>方法</strong>：作者把宿主从哺乳动物细胞换成<strong>口服益生菌</strong>。感应模块用细菌自身的葡萄糖响应转录调控因子 <strong>HexR</strong>（原本参与糖代谢调控）搭配人工合成启动子，构成一个&quot;血糖—转录&quot;转换器；效应模块是治疗性转基因。口服后工程菌<strong>暂时</strong>驻留肠道（不定植），当肠腔/宿主血糖超过正常阈值时启动表达。</p><p><strong>关键结果</strong>：在多个糖尿病小鼠模型与<strong>非人灵长类</strong>模型中显示降糖效果；长期口服还改善血脂谱，并延缓多种并发症的发展。非人灵长类数据是这条路线能否进入临床的关键门槛——很多在小鼠有效的活体药物在灵长类肠道里根本活不下来。</p><p><strong>为什么重要</strong>：真正的创新点在&quot;<strong>暂时驻留</strong>&quot;。不需要定植，意味着不需要抗生素清除、不污染肠道菌群长期组成；不需要移植，意味着没有排斥；随时停药即可撤除，把活体药物最大的安全顾虑转成了一个<strong>动力学参数</strong>（驻留时间）。这是把&quot;安全性&quot;问题转化成&quot;药代动力学&quot;问题——一个可测量、可设计的量。</p><p><strong>跨主题关联</strong>：HexR 的挪用是&quot;借现成零件&quot;的合成生物学范式，与 <code>topics/biomedicine/index.md</code> 中合成基因线路的讨论同源；&quot;传感器—执行器—反馈&quot;的三段结构，与 <code>topics/ai-brain/index.md</code> 中&quot;感知—关联—写入&quot;的闭环结构是同构的。</p><hr><h3 id="_5-macir-给-rad51-的解链机器装上-调控适配器" tabindex="-1">5. MACIR：给 RAD51 的解链机器装上&quot;调控适配器&quot; <a class="header-anchor" href="#_5-macir-给-rad51-的解链机器装上-调控适配器" aria-label="Permalink to &quot;5. MACIR：给 RAD51 的解链机器装上&quot;调控适配器&quot;&quot;">​</a></h3><p><strong>原文</strong>：Tao Zhou 等此次鉴定出 MACIR/C5orf30 是该去折叠酶的适配器：它直接结合 FIRRM，形成三元复合物，促进 RAD51 纤丝解聚，并支持醛类、铂类药物所致损伤的修复。</p><p><strong>深度扩展</strong>：</p><p>发表于 <em>PNAS</em>（2026-08-13），DOI 10.1073/pnas.2531632123。第一作者 Tao Zhou，共 12 位作者。</p><p><strong>问题背景</strong>：DNA 双链断裂是最致命的损伤形式，其中由链间交联（ICL）引起的断裂尤其棘手——铂类药物（顺铂）和醛类代谢产物都制造这类损伤，它们也正是化疗的作用基础。修复靠同源重组（HR）：RAD51 在单链 DNA 上聚合成核蛋白纤丝，寻找同源模板并完成链侵入。但纤丝<strong>不能留太久</strong>：它必须先被拆掉，下游的聚合酶与连接酶才能接手。拆得太慢，修复卡住；拆得太快，修复没完成。所以 RAD51 纤丝的拆卸是一个必须被精确计时的步骤。</p><p><strong>已有基础</strong>：FIGNL1–FIRRM（FIRRM 又名 C1orf112）复合物此前被鉴定为一种<strong>抗重组酶</strong>——它以 ATP 酶驱动的<strong>蛋白质去折叠</strong>机制把 RAD51 从纤丝上&quot;拽&quot;下来，机制上与所有已知的拆卸通路（如 RAD51 磷酸化、SWS1/SFR1 介导）都不同。去折叠酶的工作方式是机械性的：它需要一个抓手把底物送进 AAA+ 环的孔道。</p><p><strong>新发现</strong>：作者鉴定出 <strong>MACIR/C5orf30</strong> 就是这个适配器。MACIR 直接结合 FIRRM，形成 FIGNL1–FIRRM–MACIR <strong>三元复合物</strong>，从而促进 RAD51 纤丝解聚，并支持醛类与铂类药物所致损伤的修复。功能缺失实验显示：MACIR 丢失 → DNA 损伤累积、基因组不稳定、炎症信号被激活——把 MACIR 缺陷与自身免疫及肿瘤易感联系起来。</p><p><strong>为什么重要</strong>：AAA+ 去折叠酶通常自己不认识底物，需要适配器提供<strong>特异性与定位</strong>。适配器层因此是这套机器唯一可被药物靶向的接口——直接抑制 FIGNL1 的 ATP 酶会打死所有底物，而干扰 MACIR–FIRRM 界面理论上可以只影响 RAD51 这一支。临床上这指向两个方向：增敏铂类化疗（抑制拆卸、让癌细胞修不好），或在特定免疫疾病中恢复基因组稳定性。</p><p><strong>跨主题关联</strong>：机械去折叠 + 适配器定位的结构，与 <code>topics/biomedicine/index.md</code> 中蛋白稳态与分子机器条目相连；&quot;外源酶需要定位器才能对准底物&quot;这一模式，也可对照 <code>topics/ai-brain/index.md</code> 里&quot;通用能力需要具体接口才能落到场景&quot;的观察。</p><hr><h2 id="🤖-二、ai-前沿" tabindex="-1">🤖 二、AI 前沿 <a class="header-anchor" href="#🤖-二、ai-前沿" aria-label="Permalink to &quot;🤖 二、AI 前沿&quot;">​</a></h2><h3 id="_6-cm-mae-用-软对比对齐-做视觉—无线跨模态自监督预训练" tabindex="-1">6. CM-MAE：用&quot;软对比对齐&quot;做视觉—无线跨模态自监督预训练 <a class="header-anchor" href="#_6-cm-mae-用-软对比对齐-做视觉—无线跨模态自监督预训练" aria-label="Permalink to &quot;6. CM-MAE：用&quot;软对比对齐&quot;做视觉—无线跨模态自监督预训练&quot;">​</a></h3><p><strong>原文</strong>：Yubo Zhang、Yiyao Liu 提出 CM-MAE：只用 DeepSense 6G 中真实采集的 RGB 帧与 64 波束接收功率向量，不用射线追踪路径、标定深度或波束索引标签。</p><p><strong>深度扩展</strong>：</p><p>arXiv 2608.15972（2026-08-16），作者 Yubo Zhang、Yiyao Liu。</p><p><strong>问题背景</strong>：相机与无线接收机观测<strong>同一场景</strong>，只是经由不同物理信道。直觉上两者应能互相补足（看到遮挡物就能推断哪条路径断了）。但跨场景迁移极难：视角、交通流量、光照、传播几何一变，学到的表征就崩。已有工作大量依赖射线追踪仿真路径、标定深度、或波束索引标签——这些都是仿真器/标注的产物，等于把真值偷偷放进了输入。</p><p><strong>方法</strong>：CM-MAE 只吃真实测量。核心是<strong>软对比对齐损失</strong>：标准对比学习把&quot;同步的图像—无线对&quot;当唯一正例、其余全当负例；但同步样本未必是最相似的一对，而不同时刻但方向响应相近的样本会被当成假负例强行推开——这在无线域尤其严重，因为波束功率剖面对几何高度敏感但对时间不敏感。软对齐改为用实测波束功率剖面之间的相似度构造一个目标分布，让&quot;方向响应相近&quot;的样本共享正例地位。另一半是掩码联合解码器：在模态随机丢弃下重建隐藏的图像块与无线角度簇，提供局部监督。预训练后用差分速率微调——新融合头学得快、编码器动得慢，避免把通用表征毁掉。</p><p><strong>关键数字</strong>：序列不相交协议下，加软对齐把线性探针迁移均值从 24.88% 提到 29.49%；轻度融合微调在未见场景 6–8 上 77.38% Top-1，加传导式归一化适应到 78.69%。</p><p><strong>边界</strong>：作者明确写了这是表征迁移诊断，<strong>不是</strong>主动波束预测或减少扫描的声明——因为推理时用了同期的 64 波束功率向量。这种自我设限在 6G 论文里相当少见。</p><p><strong>跨主题关联</strong>：软标签替代硬正负例的做法，与 <code>topics/intelligence-self-learning/index.md</code> 中&quot;用相似度结构而非二值标签定义学习信号&quot;的讨论同源；&quot;差分速率微调&quot;的保护通用表征思路，可对照 <code>topics/ai-brain/index.md</code> 里&quot;稳定核心 + 快速外围&quot;的架构原则。</p><hr><h3 id="_7-hotfixr-用-难度定向-的合成多语数据治语言特异性能力落差" tabindex="-1">7. HOTFIXR：用&quot;难度定向&quot;的合成多语数据治语言特异性能力落差 <a class="header-anchor" href="#_7-hotfixr-用-难度定向-的合成多语数据治语言特异性能力落差" aria-label="Permalink to &quot;7. HOTFIXR：用&quot;难度定向&quot;的合成多语数据治语言特异性能力落差&quot;">​</a></h3><p><strong>原文</strong>：Ishika Agarwal 等换数据中心的视角，提出 HOTFIXR（Hardness Optimized Training data For Improving X-Lingual Reasoning）：先用模型探测学生模型的多语弱点，再针对弱点生成合成数据。</p><p><strong>深度扩展</strong>：</p><p>arXiv 2608.15964（2026-08-16），作者 Ishika Agarwal、Arkajyoti Charaborty、Tanner Sorensen、Neha Gupta 等 5 人。</p><p><strong>问题背景</strong>：语言特异性能力（LSC）是同一语义查询换语言就换答案的现象，已有工作把它归因于跨语言语义表征的内部错位。两条主流对策各有代价：<strong>全路由到英语</strong>——性能提升但表达力被锁死，非英语语种的文化/语用信息丢失；<strong>语言均衡训练</strong>——拉平差距但整体性能下降，因为等量投入意味着把算力从高收益语言挪到了低收益语言，是一种均值回归。</p><p><strong>方法</strong>：HOTFIXR 把&quot;均衡&quot;换成&quot;定向&quot;。流程是先用模型去<strong>探测</strong>学生模型具体在哪些语言、哪些任务类型上弱，然后针对这些弱点<strong>生成</strong>合成训练数据。这是一个主动学习式的闭环：数据不是按语言配额分配，而是按<strong>难度梯度</strong>分配。</p><p><strong>关键数字</strong>：3 个分布内任务、3 个分布外任务、4 种分布外语言上评估——分布内 +6.2%，微调引发的分布外灾难性遗忘减少 3.7%，分布外语言 +7.1%。第三个数字最反直觉：定向补弱<strong>同时</strong>减少了灾难性遗忘，说明弱点的成因可能与遗忘机制共享（都是表征被挤压）。</p><p><strong>为什么重要</strong>：它把多语能力问题从&quot;数据量分配&quot;重新表述为&quot;数据难度分布&quot;问题。前者受总量约束，后者只受生成质量约束——这是一个约束条件的替换，而不是优化。</p><p><strong>跨主题关联</strong>：探测弱点再定向生成，与 <code>topics/intelligence-self-learning/index.md</code> 中的自进化/自诊断循环同构；也与 <code>topics/ai-brain/index.md</code> 的&quot;缺口驱动检索&quot;——先知道不知道什么，再去补——是同一逻辑。</p><hr><h3 id="_8-不给求解器也能造出可解的-sokoban-扩散模型的-局部目标→全局性质" tabindex="-1">8. 不给求解器也能造出可解的 Sokoban：扩散模型的&quot;局部目标→全局性质&quot; <a class="header-anchor" href="#_8-不给求解器也能造出可解的-sokoban-扩散模型的-局部目标→全局性质" aria-label="Permalink to &quot;8. 不给求解器也能造出可解的 Sokoban：扩散模型的&quot;局部目标→全局性质&quot;&quot;">​</a></h3><p><strong>原文</strong>：Sina Baghal 展示了一件反直觉的事：一个纯用&quot;补格子&quot;任务训练的离散扩散 Transformer，不接触求解器、奖励、可解性标签，就能生成 77.4% 可解的关卡；而剩余失败里 94.5% 只需移掉一堵墙就能变可解。</p><p><strong>深度扩展</strong>：</p><p>arXiv 2608.15958（2026-08-16），单作者 Sina Baghal。</p><p><strong>问题背景</strong>：Sokoban 的可解性判定是 <strong>PSPACE 完全</strong>的（Culberson, 1997）——解可以指数级长，也没有短证书能快速验证&quot;这关无解&quot;。这使它成为程序化内容生成（PCG）里最难保证质量的关卡类型之一：生成器无法在生成时验证可解性，除非真的去搜索。而可解性又极其脆弱，错放一堵墙就让整关静默死掉——失败是<strong>无提示</strong>的。</p><p><strong>方法</strong>：作者不用任何求解器、奖励模型或可解性标签，只训练一个离散扩散 Transformer 做<strong>瓦片补全</strong>（masked tile completion）。这看起来与可解性完全无关。</p><p><strong>解释</strong>：差别在分解方式。自回归模型分解为 p(c_k | c_1…c_{k-1})，顺序固定、永远只条件于前缀，因此生成第 k 格时&quot;看不见&quot;后面会放什么，无法感知&quot;这堵墙和那个箱子共同构成死锁&quot;这类<strong>跨位置联合约束</strong>。掩码扩散同时条件于双向上下文，每一步都能看到全局（部分被掩码的）布局，因而有机会把死锁模式编码成局部可判别的特征。</p><p><strong>关键数字与一个漂亮的诊断</strong>：77.4% 可解；剩余失败中 94.5% 只需<strong>移掉一堵墙</strong>就能变可解。后一个数字比前一个更有信息量——它说明失败不是&quot;生成了一团乱&quot;，而是&quot;几乎全对、差一个局部决定&quot;。这是典型的&quot;模型已抓住结构但置信边界尚不精确&quot;的画像。</p><p><strong>为什么重要</strong>：一个全局的、搜索困难的属性，可以从纯局部训练目标中<strong>涌现</strong>。如果这个现象可泛化，PCG 就不需要内置求解器，只需选对生成模型的分解方式。</p><p><strong>跨主题关联</strong>：双向上下文 vs 单向前缀的差异，与 <code>topics/ai-brain/index.md</code> 中&quot;扩散式/双向联想检索 vs 顺序生成&quot;的对比同构；&quot;全局性质由局部目标涌现&quot;这一命题也是 <code>topics/philosophy/</code> 下涌现论的核心议题之一。</p><hr><h3 id="_9-nie-用智能体自己的检索轨迹微调稠密检索器" tabindex="-1">9. NIE：用智能体自己的检索轨迹微调稠密检索器 <a class="header-anchor" href="#_9-nie-用智能体自己的检索轨迹微调稠密检索器" aria-label="Permalink to &quot;9. NIE：用智能体自己的检索轨迹微调稠密检索器&quot;">​</a></h3><p><strong>原文</strong>：Shrey Shah、Levent Ozgur 研究如何用这些轨迹让已部署的稠密检索器适配变化的流程分布——不需要新相关性标注、不需要合成查询、不需要 LLM 判定。</p><p><strong>深度扩展</strong>：</p><p>arXiv 2608.15956（2026-08-16），作者 Shrey Shah、Levent Ozgur。</p><p><strong>问题背景</strong>：检索器一旦部署就常常&quot;过时&quot;——工作流变了（用户问的东西变了、语料变了），但重训需要相关性标注，成本高且慢。而智能体式检索流程（agentic RAG）在跑任务的副产品恰恰是宝贵的监督信号：它查了什么、按什么顺序看、在哪一步停下来了。这些都是<strong>真实使用分布</strong>的采样。</p><p><strong>方法</strong>：NIE（Navigation-Informed Embeddings）把停下的那份文档当<strong>软正例</strong>，并把路径上先前的文档当<strong>硬比较</strong>，按几何衰减施加序约束——越靠前的文档应越不被偏好。这个&quot;顺序即偏好&quot;的假设很轻，但它把&quot;遍历顺序&quot;这一原本被当作日志噪声的信息变成了排序监督。</p><p><strong>关键数字</strong>：从保留的源轨迹微调 BGE 编码器，独立目标基准 support Recall@20 从 72.2 提到 78.0；NIE-Stop 单独 76.9，长路径子集 52.3；NIE-Path 把长路径从 46.7 提到 55.4。<strong>打乱顺序的对照</strong>证明增益来自路径的顺序信息本身，而非仅仅多看了一些文档。</p><p><strong>为什么重要</strong>：长路径（需要多次检索的复杂问题）提升最大，而这正是当前检索系统最弱的场景。同时它提示：agent trace 是被系统性浪费的监督资源——每次智能体跑任务都在免费生产训练数据。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-brain/index.md</code> 中&quot;查询日志本身即知识&quot;的观点直接呼应；&quot;用行为轨迹替代人工标注&quot;也与 <code>topics/intelligence-self-learning/index.md</code> 的自监督思路一致。</p><hr><h3 id="_10-模型如何-选边-指令层级在残差流里是可读的" tabindex="-1">10. 模型如何&quot;选边&quot;：指令层级在残差流里是可读的 <a class="header-anchor" href="#_10-模型如何-选边-指令层级在残差流里是可读的" aria-label="Permalink to &quot;10. 模型如何&quot;选边&quot;：指令层级在残差流里是可读的&quot;">​</a></h3><p><strong>原文</strong>：在 Llama-3.1-8B 上，冲突结果从残差流激活中线性可解码，平衡准确率 0.97，比只用元数据的基线高 17 个百分点。</p><p><strong>深度扩展</strong>：</p><p>arXiv 2608.28648（2026-08-16），作者 Enrique Balp-Straffon、Chih-Hao Hsu、Rushiraj Gadhvi、Sunishchal Dev 等 6 人。</p><p><strong>问题背景</strong>：system prompt 与 user prompt 冲突时模型该听谁的，是 AI 安全的核心机制问题。实践中的观察是&quot;指令层级&quot;（instruction hierarchy）并不总被遵守，但此前缺乏一个能区分&quot;模型没学会&quot;与&quot;模型学会了但没执行&quot;的判别工具。</p><p><strong>方法</strong>：41 对带<strong>确定性验证器</strong>的成对约束基准，在基线、冲突、同信道对照三种匹配条件下测八个模型。同信道对照是关键设计——它把&quot;system 信道&quot;与&quot;system 内容&quot;分离，从而测出纯粹的信道效应（System Authority Delta）。行为上分出三档：层级尊重型、<strong>反层级型</strong>（服从 system 的次数比同信道基线预测还少）、无效应型。Llama-3.1-8B 是最强反层级案例，冲突试验中仅 0.10 服从 system。</p><p><strong>核心发现</strong>：行为失败<strong>不</strong>等于内部缺失冲突解决信号。在 Llama-3.1-8B 上，冲突结果从残差流激活中线性可解，平衡准确率 0.97，比元数据基线高 17 个百分点；Qwen2.5-7B 与 gpt-oss-20b 有类似信号。也就是说模型内部<strong>知道</strong>在冲突，但输出层没按这个信号行动。</p><p><strong>最实用的一段</strong>：用四个逐冲突逻辑回归方向的<strong>第 12 层均值</strong>做引导，真实 system 服从率从 0.132 提到 0.530；而按&quot;池化可分性&quot;（pooled separability）选出的方向引导效果很差。结论：干预成败取决于<strong>读出几何</strong>，不是探针准确率——能解码不等于能干预，这个区分对整个可解释性领域都成立。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-brain/index.md</code> 中&quot;表征可读 ≠ 行为可控&quot;的判断一致；也与 <code>topics/cybersecurity/index.md</code> 关注的提示注入防护互为表里——注入攻击本质上就是利用层级裁决的失效。</p><hr><h2 id="🧠-机制层" tabindex="-1">🧠 机制层 <a class="header-anchor" href="#🧠-机制层" aria-label="Permalink to &quot;🧠 机制层&quot;">​</a></h2><h3 id="机制一-从-离子水凝胶-到染色体凝缩——一条完整的因果链" tabindex="-1">机制一：从&quot;离子水凝胶&quot;到染色体凝缩——一条完整的因果链 <a class="header-anchor" href="#机制一-从-离子水凝胶-到染色体凝缩——一条完整的因果链" aria-label="Permalink to &quot;机制一：从&quot;离子水凝胶&quot;到染色体凝缩——一条完整的因果链&quot;">​</a></h3><p><strong>① 系统被重新定义。</strong> 传统模型把中期染色体当作&quot;被马达拉紧的聚合物&quot;，主力是 condensin 的环挤压。新框架把它当作<strong>离子水凝胶</strong>：一个带电高分子网络 + 反离子云 + 溶剂。这是软物质物理里的标准对象，其平衡体积 V 由三项自由能竞争决定——网络的橡胶弹性（倾向于收缩回无规线团尺寸）、反离子的渗透压（倾向于让网络膨胀）、聚合物—溶剂相互作用（Flory χ 参数，决定亲和/排斥）。三项之和的极小值给出 V，而 χ 或交联密度跨越临界值时，这个极小值会<strong>不连续地</strong>跳变，即体积相变（volume phase transition），数学上同构于液—气相变（一阶相变，两相共存、有滞后）。</p><p><strong>② 谁在改 χ。</strong> 组蛋白尾部富含赖氨酸与精氨酸，带正电；DNA 骨架带负电。二者之间的静电接触既是&quot;交联&quot;（把不同链段粘在一起）也是&quot;不良溶剂&quot;信号（链段更愿意彼此靠近而非与水和）。<strong>乙酰化</strong>中和赖氨酸的 ε-氨基正电荷 → 静电接触断开 → 交联密度下降、χ 向良溶剂移动 → 网络倾向膨胀 → 解凝缩。<strong>去乙酰化</strong>（HDAC）反向操作 → 接触恢复 → 凝缩。关键在于：这是一条不需要消耗 ATP 的<strong>热力学</strong>通道，与 condensin 消耗 ATP 的<strong>机械</strong>通道并行且互相补充——condensin 负责把链变短（改变拓扑与长度），组蛋白修饰负责设定&quot;在当前长度下网络想占多大体积&quot;。两者结合才能解释&quot;又短又密&quot;。</p><p><strong>③ 为什么 insight 是&quot;两态&quot;而不是&quot;连续可调&quot;。</strong> 一阶相变的标志是：在临界点附近，微小的 χ 变化导致 V 的巨大跳变，且中间体积不可稳定存在。这解释了生物学上的<strong>离散性</strong>——异染色质与常染色质是两种清晰可辨的状态，而不是一个连续谱。同时也解释了&quot;为什么细胞需要 bistability&quot;：一个数字开关比一个模拟旋钮更抗噪，这对表观遗传记忆至关重要（细胞分裂后要能可靠地&quot;记住&quot;哪块该是异染色质）。</p><p><strong>④ 可证伪预测。</strong> 若该框架成立：(a) 分离的染色体/染色质凝胶在离子强度扫描中应显示<strong>不连续的体积跳变</strong>并伴随滞后环；(b) 用 HDAC 抑制剂应能在不改变 condensin 活性的情况下使凝缩态<strong>整体塌缩</strong>回解凝缩态；(c) 温度与渗透压应能移动相变点，且移动方向可由 Flory 理论定量预测。任一条被否定，框架就需修正。</p><p><strong>⑤ 与库内知识的接口。</strong> 这套&quot;交联密度 / 相互作用参数 → 相变&quot;的语言，是 <code>topics/physics/index.md</code> 里软物质与高分子物理的直接应用；同一数学结构也出现在 <code>topics/materials/index.md</code> 的水凝胶/刺激响应材料里。更深一层：<code>topics/ai-brain/index.md</code> 的&quot;约束维持结构&quot;假说与此同构——乙酰化移除的是物理交联（结构约束），正如降低认知摩擦力移除的是思维约束，两者都表现为&quot;系统从有序态滑向无序态&quot;。</p><h3 id="机制二-反应发光为什么长期做不了超分辨——一个光子预算的硬约束" tabindex="-1">机制二：反应发光为什么长期做不了超分辨——一个光子预算的硬约束 <a class="header-anchor" href="#机制二-反应发光为什么长期做不了超分辨——一个光子预算的硬约束" aria-label="Permalink to &quot;机制二：反应发光为什么长期做不了超分辨——一个光子预算的硬约束&quot;">​</a></h3><p><strong>① 先看清超分辨的物理本质。</strong> 光学显微镜的分辨极限来自衍射：一个点源在像面形成艾里斑，两个点靠得比约 λ/2NA 更近就无法区分。所有超分辨方法都在绕过这一限制，但绕法只有两类。<strong>确定性方法</strong>（STED、SIM）靠非线性响应压缩有效点扩散函数：STED 用一束环形光通过受激辐射&quot;擦掉&quot;艾里斑边缘的发光，使有效 PSF 缩小；SIM 用结构化照明把高频信息搬移（moiré）进可探测的频带，再在频域解出。<strong>随机方法</strong>（STORM/PALM）靠时间分离：让荧光团随机、稀疏地开关，每帧只有少数孤立点发光，从而能精确定位每个点的质心（定位精度 ~ σ/√N，N 为收集到的光子数），多帧叠加重建。</p><p><strong>② 光子预算就是分母。</strong> 上面每个公式的分母都是 N——收集到的光子数。定位精度随 √N 改善；非线性方法需要足够通量才能把&quot;擦除&quot;和&quot;搬移&quot;做得干净。所以超分辨的门槛从来不是&quot;想不想得到算法&quot;，而是&quot;能不能在损伤样品之前收到足够多光子&quot;。这就是<strong>光子预算</strong>（photon budget）：样品能承受的激发剂量上限，与达到目标分辨率所需光子数之间的差距。</p><p><strong>③ 反应发光的两难。</strong> ECL/CL/BL 的优势正在于&quot;不用外部光子&quot;——激发态由化学反应产生，因此没有背景散射、没有光漂白（漂白是光化学过程）、光毒性极低。代价是：每一个发光事件产生的光子数远少于激光激发的荧光团（后者可以反复循环激发，一个分子贡献成百上千光子；化学发光通常是一次性事件，几个到几十个光子）。N 一下掉两三个数量级，√N 就掉一到一点五个数量级——分辨率直接损失。这是<strong>物理层面的</strong>限制，不是工程问题。</p><p><strong>④ RIED 的破法：从&quot;更多光子&quot;转向&quot;更好的统计&quot;。</strong> 既然 N 不能加，只能提高每个光子的<strong>信息含量</strong>。RIED 的三步各有明确作用：<strong>时空记录</strong>把发光事件的时间结构与空间位置联合编码——化学发光的动力学（衰减曲线）本身携带关于局部化学环境的信息，传统成像把它当噪声平均掉了，这里把它当信号保留；<strong>熵加权相关</strong>是关键的统计工具——相关分析能在低信噪比下提取结构（因为结构意味着邻近像素的统计相关），而熵加权给&quot;低熵区&quot;（结构明确）更高权重、压制&quot;高熵区&quot;（纯噪声），等价于一种自适应的空间正则化；<strong>反卷积</strong>最后补上光学系统 MTF 造成的频域衰减——这是纯计算步骤，把已知的系统响应反解掉，代价是放大噪声，所以必须放在熵加权之后。</p><p><strong>⑤ 这条链的可证伪点。</strong> 若 RIED 有效，其分辨率应随收集的<strong>总事件数</strong>（而非峰值强度）按 ~1/√N 改善，且改善曲线应在低光子数区仍保持斜率——如果实际在高噪声区提前饱和，说明熵加权没能有效分离信号。此外，由于不依赖外部光激发，光漂白应基本消失，可做远超 STED 的连续观察时长。</p><p><strong>⑥ 与库内知识的接口。</strong> 反卷积与 MTF 是 <code>topics/physics/index.md</code> 中傅里叶光学的标准内容；&quot;用先验结构换信噪比&quot;这一策略与 <code>topics/quantum-physics/index.md</code> 里压缩感知/量子增强测量的思路同源（都是把已知约束变成有效信息）；而&quot;改变记录方式而非增加功率&quot;的取向，与 <code>topics/ai-brain/index.md</code> 的&quot;关联复利优于堆存量&quot;是同一个经济学。</p><hr><h2 id="⚛️-第一性原理层" tabindex="-1">⚛️ 第一性原理层 <a class="header-anchor" href="#⚛️-第一性原理层" aria-label="Permalink to &quot;⚛️ 第一性原理层&quot;">​</a></h2><h3 id="原理一-一阶相变是-离散性-的唯一来源" tabindex="-1">原理一：一阶相变是&quot;离散性&quot;的唯一来源 <a class="header-anchor" href="#原理一-一阶相变是-离散性-的唯一来源" aria-label="Permalink to &quot;原理一：一阶相变是&quot;离散性&quot;的唯一来源&quot;">​</a></h3><p>生物学大量使用<strong>离散状态</strong>：基因开关的开/关、细胞周期的检查点、异染色质/常染色质、神经元动作电位的全或无。为什么自然选择偏爱离散而非连续？因为噪声是连续的。一个模拟信号在传递中会被噪声无界地侵蚀，而一个双稳态系统只要噪声幅度<strong>小于势垒高度</strong>，状态就完全不被破坏——信噪比不随距离衰减，这是数字逻辑优于模拟逻辑的根本理由。所以任何&quot;生物学的离散性&quot;背后，必须有一个提供势垒的物理机制。</p><p>热力学给出的答案就是一阶相变：自由能作为序参量的函数有两个局部极小，中间被势垒隔开。相变的<strong>协作性</strong>（cooperativity）来自多体相互作用——单个组蛋白尾部与 DNA 的静电接触很弱、会被热涨落轻易打断，但当成千上万个接触同时存在时，它们通过网络的弹性与渗透压相互耦合，形成&quot;要么一起开、要么一起关&quot;的集体行为。这是自由能极小值原理加上多体耦合的直接后果，不需要任何额外的&quot;开关蛋白&quot;。</p><p>由此得到一个可迁移的判据：<strong>当你看到一个稳定的、可遗传的、二值化的生物状态时，去找它的序参量和势垒</strong>；如果你找不到多体协作机制，那这个离散性要么来自正反馈回路（动力学双稳），要么来自化学计量（分子计数）。染色体凝缩属于前者（热力学双稳），而操纵子开关属于动力学双稳——两类机制在数学上都给双稳态，但对外部扰动的响应完全不同：热力学双稳对温度/渗透压敏感、对动力学参数不敏感，反之亦然。这是可实验区分的。</p><h3 id="原理二-分解顺序决定能否表达非局部约束" tabindex="-1">原理二：分解顺序决定能否表达非局部约束 <a class="header-anchor" href="#原理二-分解顺序决定能否表达非局部约束" aria-label="Permalink to &quot;原理二：分解顺序决定能否表达非局部约束&quot;">​</a></h3><p>Sokoban 那条结果可以上升为一个纯信息论命题。生成模型要学联合分布 p(x₁,…,xₙ)。自回归把它分解为 ∏p(xₖ|x₁…x_{k−1})，这个分解是<strong>精确</strong>的——任何联合分布都能这样写。那么为什么它学不到可解性？</p><p>因为<strong>可学性 ≠ 可表达性</strong>。分解精确，但每个条件因子必须由有限容量的函数逼近器去拟合。在自回归分解下，&quot;第 k 个格子的取值是否会导致死锁&quot;这一判断依赖<strong>尚未生成</strong>的格子——这些信息在条件里根本不存在，模型只能去近似边缘化（对所有可能的未来求期望）。当约束是&quot;存在/不存在某条路径&quot;这类<strong>全局存在性</strong>命题时，边缘化会把信号抹平：多数未来是可解的，于是局部看每一步都&quot;大概率没问题&quot;，但联合起来无解。这就是为什么自回归模型生成的关卡&quot;几乎全对、差一堵墙&quot;——它在每一格都做了局部最优决策。</p><p>掩码扩散同时条件于双向上下文，该判断所需的信息在条件里<strong>存在</strong>（至少部分存在），因此同一个函数逼近器能拟合它。结论：<strong>选择分解方式，本质上是在选择&quot;哪些条件在计算上可得&quot;</strong>。这不是模型容量的提升，而是把不可得信息变成可得信息。</p><p>可证伪预测：随掩码比例（即上下文的双向程度）从 0（纯自回归）增加到 1，可解率应单调上升；且失败样本的&quot;最小修复量&quot;（需移除的墙数）应从多堵收敛到一堵。若可解率对双向度不敏感，则该解释错误，真实原因可能在数据分布本身。</p><hr><h2 id="🔗-交叉关联" tabindex="-1">🔗 交叉关联 <a class="header-anchor" href="#🔗-交叉关联" aria-label="Permalink to &quot;🔗 交叉关联&quot;">​</a></h2><p><strong>本期十条共享一个统一逻辑：系统的行为由&quot;约束的参数&quot;决定，而不由&quot;执行者的强度&quot;决定。</strong></p><p>染色体凝缩不是 condensin 拉得更用力，而是组蛋白乙酰化把交联密度推过了相变点；压电陶瓷的突破不是把极化做得更强，而是用机器学习找到了一个此前不被认为可及的成分点；RIED 不是把发光做得更亮，而是把记录方式改成能榨取每个光子信息的形状；葡萄糖益生菌的安全性不是靠更强的控制，而是靠&quot;暂时驻留&quot;这个动力学参数；MACIR 的发现说明去折叠酶的<strong>特异性</strong>来自适配器而非马达本身。AI 侧同构：CM-MAE 的增益来自把硬正负例换成软目标分布（改标签的<strong>几何</strong>而非模型容量）；HOTFIXR 把&quot;数据均衡&quot;换成&quot;数据难度分布&quot;（改采样参数而非数据量）；Sokoban 的可解性来自分解方式（改条件可得性而非参数量）；NIE 把标注换成轨迹顺序（改监督来源而非标注预算）；指令层级的干预效果取决于<strong>读出几何</strong>而非探针准确率——论文原话就是&quot;干预成败取决于几何，不是探针准确率&quot;。</p><p>这十件事放在一起，指向一个可操作的启发式：<strong>当一个系统卡在性能天花板上时，先去找那个被固定住的参数</strong>。固定参数往往是历史偶然（单晶只能长在化学计量点上、对比学习必须有正负例、超分辨必须用外部光激发、微调必须用标注数据），而不是物理必然。找到它，问题就从&quot;更努力&quot;变成&quot;换坐标&quot;。</p><p>与库内主题的深层同构有三条：</p><p>其一，<code>topics/physics/index.md</code> 的相变语言在本期出现三次（染色体水凝胶、压电畴壁、超分辨的 MTF 截止），说明&quot;临界点附近的协作行为&quot;是一个跨尺度通用工具——从 10 nm 的染色质到 10 μm 的晶粒，同一个自由能极小值结构在起作用。</p><p>其二，<code>topics/ai-brain/index.md</code> 的核心主张——知识网络的价值来自关联密度而非节点数量——在本期被工程化验证了四次（软对齐、难度定向、双向上下文、轨迹监督）。它们都是&quot;不增加数据总量，只改变数据的组织方式&quot;，收益却稳定在 3–20% 量级。这支持一个更强的判断：<strong>当前 AI 系统的主要瓶颈不是信息不足，而是信息组织方式</strong>。</p><p>其三，<code>topics/intelligence-self-learning/index.md</code> 的自诊断循环在 HOTFIXR（探测弱点→定向生成）与 NIE（用自身轨迹改自身）中被具体实现。这两篇的共同点是：系统把自己的<strong>运行痕迹</strong>当作改进信号来源，不需要外部教师。这正是 <code>topics/cross-domain-synthesis-2026-q3.md</code> 里&quot;闭环自改&quot;这条线在 8 月的两个实例。</p><p>一句话收束：<strong>本期最反直觉的发现是&quot;可读≠可控&quot;（指令层级论文）和&quot;局部训练可导出全局性质&quot;（Sokoban）</strong>——前者说明解释性与可控性之间有一道真实的鸿沟，后者说明这道鸿沟在另一个方向上可以被绕过。</p><hr><p>关键词：染色体凝缩, 体积相变, 离子水凝胶, 组蛋白乙酰化, condensin, 环挤压, Roger Kornberg, 10.1126/science.adz1083, 织构压电陶瓷, d33, 居里温度, PIN-PSN-PT, 机器学习材料搜索, 10.1126/science.aei0475, 超分辨成像, 反应发光, 电化学发光 ECL, 熵加权相关, 反卷积, RIED, 光子预算, 10.1038/s41586-026-10889-7, 葡萄糖响应益生菌, HexR, 合成生物学, 活体药物, 非人灵长类, 10.1038/s41586-026-10909-6, RAD51, 同源重组, FIGNL1, FIRRM, MACIR, C5orf30, AAA+ 去折叠酶, 10.1073/pnas.2531632123, CM-MAE, 跨模态自监督, 软对比对齐, DeepSense 6G, 2608.15972, HOTFIXR, 语言特异性能力 LSC, 合成多语数据, 灾难性遗忘, 2608.15964, Sokoban, PSPACE 完全, 离散扩散模型, 程序化内容生成, 2608.15958, Navigation-Informed Embeddings, 稠密检索, Recall@20, agent trace, 2608.15956, 指令层级, System Authority Delta, 残差流线性探针, 激活引导, Llama-3.1-8B, 2608.28648</p><p>关联：topics/physics/index.md, topics/materials/index.md, topics/biomedicine/index.md, topics/ai-brain/index.md, topics/intelligence-self-learning/index.md, topics/quantum-physics/index.md, topics/cybersecurity/index.md, topics/cross-domain-synthesis-2026-q3.md, topics/science-news/index.md, science-log/src/reconstructed/2026-08-16.md</p>',143)])])}const h=t(e,[["render",g]]);export{c as __pageData,h as default};
